from review import card,save,DATE
def b(title,text,citation='primary'):return dict(title=title,text=text,citation=citation)
i='TCS-3007';_,c=card(i);refs=c['references'];refs[0]['locator']='CCC 2021, article 41: Definition 1 (target-field rigidity), Section 1.4, equations (1)–(2), Theorem 7 and Problem 10, p. 41:4. The imported Conjecture 9 locator refers to the preceding weaker separation question; the extracted r² target is Problem 10. The parameter is √2, not 2.'
save(i,dict(title='Maximal rational rigidity despite a quadratic-field diagonal correction',formal='For infinitely many positive integers r, is there a matrix A∈C_r(ℚ,√2) with R_ℚ(A,r)=r²? Equivalently, for every R≥1 there exist r≥R, a rational 2r×2r matrix M and a rational diagonal matrix D such that rank_{ℚ(√2)}(M+√2·I_{2r})≤r, A=M+D, and every rational matrix Z with fewer than r² nonzero entries satisfies rank_ℚ(A+Z)>r. Membership in C_r already ensures R_{ℚ(√2)}(A,r)≤2r. No effective construction or bound on rational entry sizes is part of the source question.',definitions='ℚ is the rational field and ℚ(√2)={a+b√2:a,b∈ℚ}, with (√2)²=2. I_{2r} is the identity matrix. Rank over a field is the dimension of the span of a matrix’s columns over that field. For A∈ℚ^{2r×2r} and an extension field L⊇ℚ, define R_L(A,r)=min{|{(i,j):Zᵢⱼ≠0}|: Z∈L^{2r×2r}, rank_L(A+Z)≤r}. The cost counts changed entries, regardless of their magnitudes or bit encodings. Set D_r(ℚ,√2)={M∈ℚ^{2r×2r}:rank_{ℚ(√2)}(M+√2·I_{2r})≤r} and C_r(ℚ,√2)={M+D:M∈D_r(ℚ,√2), D∈ℚ^{2r×2r} diagonal}. All off-diagonal entries of D are zero. The rational rigidity R_ℚ is also called strict rigidity here, because rational matrices have field of definition ℚ. Changes in a larger field are measured separately. For every rational 2r×2r matrix the general upper bound R_ℚ(A,r)≤r² holds, so the target equality is maximal possible rigidity at target rank r. Infinite occurrence means unbounded r, not all sufficiently large r.',question_type='yes_no',answer_criterion='Prove that the stated maximal-rigidity matrices exist for unbounded r, or refute the statement by proving that for all sufficiently large r every A∈C_r(ℚ,√2) has rational rigidity strictly below r². A superlinear lower bound smaller than r², a constant-factor field separation, or finitely many verified examples does not settle this exact maximality question.',context_blocks=[b('The allowed replacement field can matter','The matrix itself is rational in both comparisons. Only the field from which changed entries may be chosen differs. An irrational correction can lower rank even when rational corrections with the same sparse pattern cannot.','primary'),b('The source class has a built-in sparse extension-field correction','For A=M+D in the stated class, changing diagonal entries by √2·I−D reaches rank at most r over ℚ(√2). Thus at most 2r changes suffice over that field, while the conjecture asks for the maximal r² changes over ℚ.','primary'),b('The current source lower bound is linear','Theorem 7 gives a matrix in C_r with rational rigidity at least 3r−2 for every r≥3. This proves a separation, but is far below the exact quadratic target.','primary'),b('This is stronger than the preceding conjecture','Conjecture 9 asks for a superlinear rational rigidity lower bound with only linearly many extension-field changes. Problem 10 asks for maximal rational rigidity inside the specified class. The two questions have different answer thresholds.','primary')],why='Would show that adjoining one quadratic irrational can reduce the number of entries needed to lower matrix rank from quadratic to linear, exposing an extreme field dependence of rigidity.',references=refs,progress=[dict(date='2021',text='The source proves R_ℚ(A,r)≥3r−2 for some A∈C_r for each r≥3 and poses the exact r² target as Problem 10.',citation='primary')],status='source_open',status_note='Read the full field-dependent definitions, class construction and exact Problem 10; checked the author-hosted paper and later targeted literature searches through 12 September 2026. No resolution of the r² target in C_r(ℚ,√2) was located. The dated source remains the basis for open status.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='An extremal field-dependence question for matrix rigidity, linking algebraic restrictions on sparse corrections to a core linear-circuit complexity measure. Existing score retained.',assessed_on=DATE),review_note='Restored the missing square root, expanded C_r and R_ℚ, corrected the source locator to Problem 10 and preserved the exact infinitely-many-orders target without adding an explicit-construction requirement.',working_summary=dict(sentences=['The input class consists of rational matrices that become rank at most half their order after a quadratic-field diagonal correction.','At most 2r entries need change when values from ℚ(√2) are allowed.','The question asks whether rational-only changes can require the maximum r² entries for infinitely many orders.','The source proves only a linear rational lower bound within this class.','The exact quadratic target would demonstrate an extreme dependence of rigidity on the permitted field.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary'])),notes=['Restored √2 and corrected Conjecture 9 to the exact Problem 10.','Defined both rigidity fields and the restricted matrix class.','Specified the infinitely-many-r quantifier and exact maximality criterion.','Checked the primary results and searched later work.'],checked_sources=[r['url'] for r in refs]+['https://math.uchicago.edu/~bkivva/files/articles/LIPIcs-CCC-2021-41.pdf'])
